"""Generate initial static sheet templates. No runtime Python dependency."""
from pathlib import Path

def write(path, text):
    p = Path(path)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(text, encoding='utf-8')

def field(label, key, number=False):
    attr = ' type="number" min="0" step="1"' if number else ''
    maxima = {'health.value': 'system.health.max', 'armor.value': 'system.armor.max',
              'ardor.burnt': 'ardorBurntLimit', 'ardor.installed': 'ardorInstalledLimit'}
    if key in maxima:
        attr += ' max="{{' + maxima[key] + '}}"'
    if key == 'ardor.max':
        attr = attr.replace('min="0"', 'min="{{ardorMinimumMax}}"')
    return f'<label>{label}<input name="system.{key}" value="{{{{system.{key}}}}}"{attr}></label>'

def group(title, fields):
    return '<fieldset {{#unless editable}}disabled{{/unless}}><legend>'+title+'</legend><div class="grid">'+''.join(field(*f) for f in fields)+'</div></fieldset>'

