item += """{{#if isWeapon}}
<fieldset {{#unless editable}}disabled{{/unless}}><legend>Cost</legend><label>Magnetite (Mag)<input name="system.magCost" type="number" min="0" step="1" value="{{system.magCost}}"></label></fieldset>
<fieldset {{#unless editable}}disabled{{/unless}}><legend>Ammo</legend><label>Weapon ammo family<select name="system.ammoFamily">{{selectOptions ammoFamilies selected=system.ammoFamily}}</select></label><label>Selected ammo stack<select name="system.ammoId">{{selectOptions ammoSources selected=system.ammoId}}</select></label><details><summary>Legacy inline ammo</summary><div class="grid"><label>Type<input name="system.ammo.type" value="{{system.ammo.type}}"></label><label>Quantity<input type="number" min="0" step="1" name="system.ammo.quantity" value="{{system.ammo.quantity}}"></label></div></details></fieldset>
<fieldset {{#unless editable}}disabled{{/unless}}><legend>Upgrade</legend><label>Path<select name="system.upgrade">{{selectOptions upgradeChoices selected=system.upgrade}}</select></label><p data-preview="upgrade">{{weaponDetails.description}}</p><p data-preview="attack">Total attack bonus: +{{weaponDetails.attack}} · DR: {{weaponDetails.dr}}</p></fieldset>
<fieldset {{#unless editable}}disabled{{/unless}}><legend>Affinity (optional)</legend><select name="system.affinity" aria-label="Weapon affinity">{{selectOptions affinityChoices selected=system.affinity}}</select>{{#if system.affinity}}<p>Affinity uses one mod slot.</p>{{/if}}</fieldset>
<fieldset {{#unless editable}}disabled{{/unless}}><legend>Attack profile</legend><label>Weapon type<select name="system.weaponType">{{selectOptions weaponTypeChoices selected=system.weaponType}}</select></label><label>Base range (m)<input type="number" min="1" step="1" name="system.range" value="{{system.range}}"></label><label>Base damage type<select name="system.damageType">{{selectOptions damageChoices selected=system.damageType}}</select></label><p data-preview="profile">Range {{profile.range}} m; {{profile.hands}} hand(s); {{profile.actions}} action(s); {{profile.damage}}.</p><details><summary>Inherent modifiers</summary><div class="modifier-grid">{{#each inherentModifiers}}<label><input type="checkbox" name="system.properties.{{key}}" {{checked checked}}> {{label}}</label>{{/each}}</div></details></fieldset>
<section><h2>Mods</h2>{{#each modSlots}}<div class="weapon-mod-slot" data-mod-slot="{{slot}}"><span>Mod {{number}}</span>{{#if mod}}<span class="weapon-mod-name" tabindex="0">{{mod.name}}<span class="weapon-mod-tooltip" role="tooltip">{{{mod.html}}}</span></span><button type="button" data-action="removeMod" data-mod-slot="{{slot}}" {{#unless ../editable}}disabled{{/unless}}>Remove</button>{{else}}<span>Drop a Weapon Mod here</span>{{/if}}</div>{{else}}<p>Affinity occupies the available slot.</p>{{/each}}</section>
{{/if}}{{/unless}}"""
item += '''<label>{{#if isWeaponMod}}Description{{else if isFashion}}Abilities{{else if isLicense}}Notes{{else}}Description &amp; effects{{/if}}</label>{{#if editable}}<prose-mirror name="system.description" value="{{descriptionEditor}}" data-document-uuid="{{item.uuid}}">{{{descriptionHTML}}}</prose-mirror>{{else}}<div class="rich-content">{{{descriptionHTML}}}</div>{{/if}}</section>'''
item = item.rsplit('</section>',1)[0] + '''<section><h2>Active Effects</h2>{{#if editable}}<button type="button" data-action="createEffect">Add Effect</button>{{/if}}<ul class="inventory">{{#each effects}}<li><span>{{name}} · {{status}}<small class="effect-source">Source: {{source}}</small>{{#if changes}}<small class="effect-changes">{{changes}}</small>{{/if}}{{#if suppressed}}<small class="effect-source">Activate or equip the source item to apply this effect.</small>{{/if}}</span><button type="button" data-action="editEffect" data-effect-id="{{id}}" data-effect-item-id="{{itemId}}">Edit</button>{{#if ../editable}}<button type="button" data-action="toggleEffect" data-effect-id="{{id}}" data-effect-item-id="{{itemId}}">{{#if disabled}}Enable{{else}}Disable{{/if}}</button><button type="button" data-action="removeEffect" data-effect-id="{{id}}" data-effect-item-id="{{itemId}}">Remove</button>{{/if}}</li>{{/each}}</ul></section>''' + '</section>'
item = item.replace('</header>', '</header><nav class="swords-nav" aria-label="Item sections"><button type="button" data-action="sheetPanel" data-panel="overview">Details</button>{{#if isWeapon}}<button type="button" data-action="sheetPanel" data-panel="combat">Weapon</button>{{else if hasSpecialAttacks}}<button type="button" data-action="sheetPanel" data-panel="combat">Special Abilities</button>{{/if}}<button type="button" data-action="sheetPanel" data-panel="notes">Description</button><button type="button" data-action="sheetPanel" data-panel="effects">Effects</button></nav>',1)
special = '{{#if hasSpecialAttacks}}<fieldset {{#unless editable}}disabled{{/unless}}><legend>Special Abilities</legend><button type="button" data-action="addSpecialAttack">Add Special Ability</button>{{#each specialAttacks}}<fieldset class="special-attack"><legend>{{name}}</legend><label>Name<input name="system.specialAttacks.{{@index}}.name" value="{{name}}" required></label><div class="grid">'
special += '<label>Area shape<select name="system.specialAttacks.{{@index}}.areaShape">{{selectOptions ../areaChoices selected=areaShape}}</select></label><label>Area radius / length (m)<input type="number" min="0" name="system.specialAttacks.{{@index}}.areaSize" value="{{areaSize}}"></label><label>Area placement range (m)<input type="number" min="0" name="system.specialAttacks.{{@index}}.areaRange" value="{{areaRange}}"></label>'
special += '<label>Mode<select name="system.specialAttacks.{{@index}}.mode">{{selectOptions ../abilityModes selected=mode}}</select></label><label class="special-hostile"><input type="checkbox" name="system.specialAttacks.{{@index}}.hostile" {{checked hostile}}> Hostile action</label>'
for label,key in [('AP cost','apCost'),('Burn Ardor','burnArdor'),('Install Ardor','installArdor'),('Attack bonus','bonus')]:
    minimum = '' if key == 'bonus' else ' min="0"'
    special += '<label>'+label+'<input type="number" step="1"'+minimum+' name="system.specialAttacks.{{@index}}.'+key+'" value="{{'+key+'}}"></label>'
for label,key,choices in [('Attack pool','attackPool','poolChoices'),('Defense pool','defensePool','poolChoices'),('Damage type','damageType','damageChoices')]:
    special += '<label>'+label+'<select name="system.specialAttacks.{{@index}}.'+key+'">{{selectOptions ../'+choices+' selected='+key+'}}</select></label>'
special += '<label>Weapon requirement<select name="system.specialAttacks.{{@index}}.weaponRequirement">{{selectOptions ../weaponRequirements selected=weaponRequirement}}</select></label><label class="special-hostile"><input type="checkbox" name="system.specialAttacks.{{@index}}.inheritWeaponDamage" {{checked inheritWeaponDamage}}> Use weapon damage type</label><label>Modifiers (comma separated)<input name="system.specialAttacks.{{@index}}.modifiers" value="{{modifiers}}"></label><label>Range override (m; 0 = weapon)<input type="number" min="0" name="system.specialAttacks.{{@index}}.range" value="{{range}}"></label><label>Extra Wounds per 5 or 6<input type="number" min="0" name="system.specialAttacks.{{@index}}.fivePlusExtra" value="{{fivePlusExtra}}"></label><label>Extra Wounds per Critical Strike<input type="number" min="0" name="system.specialAttacks.{{@index}}.criticalExtra" value="{{criticalExtra}}"></label><label class="special-hostile"><input type="checkbox" name="system.specialAttacks.{{@index}}.allCritical" {{checked allCritical}}> All Strikes are Critical</label><label class="special-hostile"><input type="checkbox" name="system.specialAttacks.{{@index}}.activation" {{checked activation}}> Activates this Technick (reserve installed Ardor; Release from the item)</label>'
special += '<label class="special-hostile"><input type="checkbox" name="system.specialAttacks.{{@index}}.variableBurn" {{checked variableBurn}}> Ask for Burn Ardor</label><label class="special-hostile"><input type="checkbox" name="system.specialAttacks.{{@index}}.releaseInstallation" {{checked releaseInstallation}}> Release parent installation when used</label><label class="special-hostile"><input type="checkbox" name="system.specialAttacks.{{@index}}.addSidhi" {{checked addSidhi}}> Add Sidhi to pool</label><label class="special-hostile"><input type="checkbox" name="system.specialAttacks.{{@index}}.convertStrikes" {{checked convertStrikes}}> Treat rolled 4+ as 6 for resolution</label>'
special += '<label class="special-hostile"><input type="checkbox" name="system.specialAttacks.{{@index}}.uninterruptible" {{checked uninterruptible}}> Uninterruptible</label>'
special += '<label>Target modifier<select name="system.specialAttacks.{{@index}}.effectKey">{{selectOptions ../targetEffectChoices selected=effectKey}}</select></label><label>Modifier amount<input type="number" step="1" name="system.specialAttacks.{{@index}}.effectValue" value="{{effectValue}}"></label></div><p>Optional modifier: apply or remove on selected targets from the activation chat card. Record range, duration, and exceptions below.</p><label>Description</label><prose-mirror name="system.specialAttacks.{{@index}}.description" value="{{description}}"></prose-mirror><button type="button" data-action="removeSpecialAttack" data-index="{{@index}}">Remove Special Ability</button></fieldset>{{/each}}</fieldset>{{/if}}'
item = special.join(item.rsplit('</section>',1)) + '</section>'
write('templates/item.hbs',item)
write('templates/browser.hbs', '''<section class="archive-layout"><header class="archive-header"><span class="eyebrow">10,000 SWORDS AGAINST HEAVEN</span><h2>Compendium Browser</h2><p>Find an item. Drag it onto your character.</p></header><div class="archive-filters"><label>Search<input data-filter="query" type="search" value="{{filters.query}}" placeholder="Name, type, or source…" aria-label="Search compendiums"></label><label>Type<select data-filter="type"><option value="">All types</option>{{selectOptions types selected=filters.type}}</select></label><label>Source<select data-filter="source"><option value="">All sources</option>{{selectOptions sources selected=filters.source}}</select></label><button type="button" data-action="refresh" title="Reload compendium indexes">Refresh</button></div><p class="archive-count">{{shown}} of {{count}} entries</p>{{#if failures}}<p class="capacity-warning">Could not load: {{failures}}. Try Refresh.</p>{{/if}}<ul class="archive-results">{{#each rows}}<li draggable="true" data-uuid="{{uuid}}"><img src="{{img}}" alt="" loading="lazy"><div><strong>{{name}}</strong><small>{{typeLabel}} · {{source}}</small></div><button type="button" data-action="inspect" data-uuid="{{uuid}}">View</button></li>{{else}}<li class="archive-empty">No matching items. Try another filter, create a world item, or enable an Item compendium.</li>{{/each}}</ul>{{#if more}}<button type="button" data-action="more">Load more</button>{{/if}}</section>''')

write('templates/item-creator.hbs', '''<section class="creator-layout"><header><span class="eyebrow">THIS IS 1 SWORD AGAINST HEAVEN</span><h2>Build your collection</h2><p>Create an item, then keep going. Your selected type stays ready.</p></header><div class="creator-scroll"><fieldset><legend>Item identity</legend><div class="creator-grid"><label>Destination folder<select name="folder">{{selectOptions folders selected=folder}}</select></label><label>Item type<select name="itemType">{{selectOptions types selected=type}}</select></label><label>Name<input name="name" value="{{name}}" required placeholder="Name your item" autocomplete="off"></label></div></fieldset><fieldset><legend>Details</legend><div class="creator-grid">{{{fields}}}</div></fieldset><fieldset><legend>Description &amp; abilities</legend><prose-mirror name="system.description" value="{{description}}"></prose-mirror></fieldset><p class="creator-hint">Use Edit last created for artwork, Active Effects, and drag-and-drop weapon mods.</p></div><footer class="creator-footer">{{#if batch}}<details open><summary>Batch queue ({{batch.length}})</summary><ul class="creator-queue">{{#each batch}}<li>{{name}} · {{type}} <button type="button" data-action="removeQueued" data-index="{{index}}">Remove</button></li>{{/each}}</ul><button type="button" data-action="createBatch">Import queued items</button></details>{{/if}}<p role="status" aria-live="polite">{{#if lastName}}Created {{lastName}} · {{count}} this session{{else}}Items are saved to the Items directory.{{/if}}</p><div><button type="button" data-action="bulk">Import files / rulebook text</button>{{#if lastName}}<button type="button" data-action="editLast">Edit last created</button>{{/if}}<button type="button" data-action="queue">Add to batch</button><button type="submit" class="creator-primary">Create item</button></div></footer></section>''')

# Shared importer tabs keep previews and drafts in the same persistent application.
creator = Path('templates/item-creator.hbs').read_text(encoding='utf-8')
nav = '<nav class="swords-nav" aria-label="Import mode"><button type="button" data-action="importTab" data-tab="single">Item Importer</button><button type="button" data-action="importTab" data-tab="mass">Mass Importer</button><button type="button" data-action="importTab" data-tab="world">World Beings</button></nav>'
creator = creator.replace('</header>', '</header>'+nav+'{{#if isSingle}}', 1)
creator = creator.replace('<button type="button" data-action="bulk">Import files / rulebook text</button>', '')
mass = '''<div class="creator-scroll"><fieldset><legend>{{#if isWorld}}World Being stat blocks{{else}}Mass Importer{{/if}}</legend>{{#if isWorld}}<p>Paste complete stat blocks with an uppercase name, HEALTH line, Cultivations, and bracketed item sections. Matching prefers world items, then visible Item compendiums; Microcosmic Orbit searches only Technicks and Magicks. Missing items become placeholders. Multiple complete blocks are supported.</p>{{else}}<ol><li>Choose a format and default item type. For book Traits, choose Rulebook text and Trait.</li><li>Paste complete entries including their numbered headings (for example, 2 4 Adamance). For unnumbered entries, use a Name: heading for each item or a line containing --- between entries.</li><li>Preview and check the count and names. If multiple items appear as one, add separators and preview again.</li><li>Review the editable JSON, then import. The window stays open.</li></ol><div class="creator-grid"><label>Destination folder<select name="folder">{{selectOptions folders selected=folder}}</select></label><label>Format<select name="import.format">{{selectOptions formats selected=importState.format}}</select></label><label>Default item type<select name="import.type">{{selectOptions types selected=importState.type}}</select></label></div>{{/if}}<label>Files (optional, multiple allowed)<input type="file" name="import.files" multiple accept=".json,.csv,.txt"></label><label>Source content<textarea name="import.content" rows="10">{{importState.content}}</textarea></label><button type="button" data-action="previewImport">Preview entries</button></fieldset><p role="status">{{importState.status}}</p>{{#if importState.names}}<fieldset><legend>Detected entries ({{importState.names.length}})</legend><ol>{{#each importState.names}}<li>{{this}}</li>{{/each}}</ol></fieldset>{{/if}}{{#if importState.notes}}<details><summary>Review notes</summary><ul>{{#each importState.notes}}<li>{{this}}</li>{{/each}}</ul></details>{{/if}}<label>Editable preview (JSON)<textarea name="import.review" rows="16">{{importState.review}}</textarea></label><p>Nothing is created until you press Import preview. Successful entries leave the preview; failed entries remain available to correct.</p></div><footer class="creator-footer"><button type="button" class="creator-primary" data-action="commitImport">Import preview</button></footer>'''
creator = creator.rsplit('</section>', 1)[0]+'{{else}}'+mass+'{{/if}}</section>'
write('templates/item-creator.hbs', creator)
browser = Path('templates/browser.hbs').read_text(encoding='utf-8').replace('Name, type, or source…','Name, tag:fire, sect:asuri, sidhi:2…').replace('<p class="archive-count">','<p>Search names and descriptions, or use tag:, sect:, sidhi:, rank:, and rarity: filters.</p><p class="archive-count">')
write('templates/browser.hbs', browser)

item = Path('templates/item.hbs').read_text(encoding='utf-8')
item = item.replace('{{else if isAbility}}<fieldset', '{{else if isGambit}}<fieldset><legend>World Being Gambit</legend><label>AP cost (✦)<input name="system.apCost" type="number" min="0" value="{{system.apCost}}"></label><label>Tags<input name="system.tags" value="{{system.tags}}"></label><label>Rules reference<input name="system.source" value="{{system.source}}"></label></fieldset>{{else if isAbility}}<fieldset')
item = item.replace('<h2>{{#if isAmmo}}', '<h2>{{#if isGambit}}World Being Gambit{{else if isAmmo}}')
grantZone = '<section><h2>Starting Items &amp; Traits</h2><p>This loadout belongs only to {{item.name}}. Changing Jobs replaces its granted items; manually added items stay.</p>{{#each jobGrantGroups}}<fieldset data-job-grants data-grant-type="{{type}}"><legend>{{label}}</legend><ul class="inventory">{{#each items}}<li data-tooltip="{{tooltip}}"><span>{{name}}</span><button type="button" data-action="removeGrant" data-grant-id="{{id}}">Remove</button></li>{{else}}<li>Drop an item here</li>{{/each}}</ul></fieldset>{{/each}}</section>'
item = item.replace('{{#if isJob}}<fieldset', '{{#if isJob}}'+grantZone+'<fieldset',1)
item = item.replace('<legend>Ability details</legend>', '<legend>Ability details</legend>')
item = item.replace('{{#if isAbility}}<fieldset', '{{#if isAbility}}<fieldset><legend>Library metadata</legend><label>Sect<input name="system.sect" value="{{system.sect}}"></label><label>Sidhi Stage<input name="system.sidhi" type="number" min="0" max="6" value="{{system.sidhi}}"></label></fieldset><fieldset',1)
write('templates/item.hbs',item)
actor = Path('templates/actor.hbs').read_text(encoding='utf-8')
start=actor.index('<section><h2>Gear &amp; Abilities</h2>')
end=actor.index('<section><h2>Notes</h2>',start)
groups='''{{#each inventoryGroups}}<section><h2>{{label}}</h2><div class="section-tools"><button type="button" data-action="addNew" data-item-type="{{type}}">Add New</button><button type="button" data-action="autoSort" data-item-type="{{type}}">Auto-sort</button></div><ul class="inventory">{{#each items}}<li data-item-id="{{id}}" data-rarity="{{system.rarity}}"><span>{{name}} {{#if system.quantity}}× {{system.quantity}}{{/if}}</span><button type="button" data-action="editItem" data-item-id="{{id}}">Edit</button>{{#if canConsume}}<button type="button" data-action="useConsumable" data-item-id="{{id}}">Use</button>{{/if}}{{#if equippable}}<button type="button" data-action="toggleEquipment" data-item-id="{{id}}">{{#if system.equipped}}Unequip{{else}}Equip{{/if}}</button>{{/if}}<button type="button" data-action="removeEquipment" data-item-id="{{id}}">Remove</button></li>{{else}}<li>No items yet.</li>{{/each}}</ul></section>{{/each}}'''
actor=actor[:start]+groups+actor[end:]
write('templates/actor.hbs',actor)

# Unified ability actions and explicit costs in Inventory and Combat.
actor=Path('templates/actor.hbs').read_text(encoding='utf-8')
costs='<small class="ability-costs">AP {{system.apCost}} ✦ · Burn {{system.burnArdor}} ✹ · Install {{system.installArdor}} ❂</small>'
controls='{{#if configuredActions}}{{#if internalized}}<button type="button" data-action="toggleEquipment" data-item-id="{{id}}">Release</button>{{else}}<small>Use Special Abilities in Combat</small>{{/if}}{{else}}<button type="button" data-action="{{#if internalized}}toggleEquipment{{else}}useAbility{{/if}}" data-item-id="{{id}}">{{#if internalized}}Release{{else}}{{actionLabel}}{{/if}}</button>{{/if}}'
actor=actor.replace('<span><strong>{{name}}</strong> · {{system.apCost}} ✦ · {{system.installArdor}} ❂</span>', '<span><strong>{{name}}</strong>'+costs+'</span>')
actor=actor.replace('<button type="button" data-action="toggleEquipment" data-item-id="{{id}}" {{#unless ../../editable}}disabled{{/unless}}>{{#if system.equipped}}Release{{else}}Internalize{{/if}}</button>{{#if system.equipped}}<button type="button" data-action="useAbility" data-item-id="{{id}}">Use</button>{{/if}}',controls)
actor=actor.replace('<span><strong>{{name}}</strong></span>', '<span><strong>{{name}}</strong>{{#if isAbility}}'+costs+'{{/if}}</span>')
actor=actor.replace('{{#if canCast}}<button type="button" data-action="cast" data-item-id="{{id}}">Cast</button>{{/if}}{{#if canUse}}<button type="button" data-action="useAbility" data-item-id="{{id}}">Use</button>{{/if}}','{{#if isAbility}}'+controls+'{{/if}}')
actor=actor.replace('Equip weapons, Magicks, or Technicks from Inventory.', 'Equip weapons or add Magicks and Technicks from Inventory.')
write('templates/actor.hbs',actor)

# Keep the importer layout in a readable, dedicated source template.
write("templates/item-creator.hbs", Path("tools/templates/item-creator.hbs").read_text(encoding="utf-8"))
